-- Historical entity-derived SQLite fixture from supplied v2 archive. Not an exported Room schema or a production database.
-- Entities.kt SHA256: da11e046e1e86df69ec6fae1121579a8f4b4f5ccf7b41a172d1d4cf7986bade8
CREATE TABLE `projects` (`id` INTEGER NOT NULL, `name` TEXT NOT NULL, `hfSourceRepo` TEXT NOT NULL, `hfDestRepo` TEXT NOT NULL, `sourceConfig` TEXT NOT NULL, `sourceSplit` TEXT NOT NULL, `imageColumn` TEXT NOT NULL, `idColumn` TEXT NOT NULL, `targetSplit` TEXT NOT NULL, `activeTasksCsv` TEXT NOT NULL, `classesCsv` TEXT NOT NULL, `diskBudgetMb` INTEGER NOT NULL, `modelPath` TEXT, `modelConfigJson` TEXT, `prefetchEnabled` INTEGER NOT NULL, `lastRowCursor` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `batches` (`projectId` INTEGER NOT NULL, `batchNumber` INTEGER NOT NULL, `status` TEXT NOT NULL, `totalCases` INTEGER NOT NULL, `validatedCases` INTEGER NOT NULL, `rejectedCases` INTEGER NOT NULL, `deferredCases` INTEGER NOT NULL, `hfCommitSha` TEXT, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`projectId`,`batchNumber`));
CREATE TABLE `samples` (`sampleId` TEXT NOT NULL, `projectId` INTEGER NOT NULL, `batchNumber` INTEGER NOT NULL, `assetId` TEXT NOT NULL, `sourceRowIndex` INTEGER NOT NULL, `sourceFileUrl` TEXT, `localImagePath` TEXT, `imageWidth` INTEGER NOT NULL, `imageHeight` INTEGER NOT NULL, `sha256` TEXT, `phash` INTEGER, `groupId` TEXT, `split` TEXT NOT NULL, `acquisitionStatus` TEXT NOT NULL, `annotationStatus` TEXT NOT NULL, `syncStatus` TEXT NOT NULL, `auditReason` TEXT, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`sampleId`));
CREATE TABLE `annotations` (`sampleId` TEXT NOT NULL, `dataJson` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`sampleId`));
CREATE TABLE `audit_logs` (`id` INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, `sampleId` TEXT, `batchNumber` INTEGER NOT NULL, `action` TEXT NOT NULL, `details` TEXT NOT NULL, `timestamp` INTEGER NOT NULL);
